func newEscrowTransaction() unsafe.Pointer { return unsafe.Pointer(new(payescrow.EscrowTransaction)) }

func newNEscrowTransaction(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]payescrow.EscrowTransaction, n)))
}

func ptrEscrowTransaction(p unsafe.Pointer, c int32) any {
	r := (*payescrow.EscrowTransaction)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.EscrowAccountID))
	case 4:
		return (*string)(unsafe.Pointer(&r.Type))
	case 5:
		return &r.AmountMinor
	case 6:
		return &r.BalanceAfterMinor
	case 7:
		return &r.OccurredDate
	case 8:
		return &r.Description
	case 9:
		return (**string)(unsafe.Pointer(&r.SettlementID))
	case 10:
		return (*string)(unsafe.Pointer(&r.CreatedByID))
	case 11:
		return &r.CreatedAt
	}
	return nil
}

func valueEscrowTransaction(p unsafe.Pointer, c int32) any {
	r := (*payescrow.EscrowTransaction)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.EscrowAccountID)
	case 4:
		return string(r.Type)
	case 5:
		return r.AmountMinor
	case 6:
		return r.BalanceAfterMinor
	case 7:
		return r.OccurredDate
	case 8:
		if r.Description == "" {
			return nil
		}
		return r.Description
	case 9:
		if r.SettlementID == nil {
			return nil
		}
		return string(*r.SettlementID)
	case 10:
		if r.CreatedByID == "" {
			return nil
		}
		return string(r.CreatedByID)
	case 11:
		return r.CreatedAt
	}
	return nil
}

func attachEscrowTransaction(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*payescrow.EscrowTransaction)(p)
	switch rel {
	case 0:
		r.EscrowAccount = (*payescrow.EscrowAccount)(child)
	}
}

